def generate_image(prompt, output_path, model="google/gemini-2.5-flash-image", retries=2):
    """Generate a single image"""
    url = "https://openrouter.ai/api/v1/chat/completions"
    headers = {
        "Authorization": f"Bearer {API_KEY}",
        "Content-Type": "application/json",
        "HTTP-Referer": "https://hermes.local",
        "X-Title": "Hermes Book Cover Generation"
    }

    for attempt in range(retries + 1):
        try:
            payload = {
                "model": model,
                "messages": [{"role": "user", "content": [{"type": "text", "text": prompt}]}]
            }
            print(f"  Calling {model} (attempt {attempt+1})...")
            resp = requests.post(url, json=payload, headers=headers, timeout=180)

            if resp.status_code != 200:
                print(f"  API error {resp.status_code}, attempt {attempt+1}")
                if attempt < retries:
                    time.sleep(5)
                    continue
                return None

            result = resp.json()
            images = result["choices"][0]["message"].get("images", [])
            if not images:
                print(f"  No images, attempt {attempt+1}")
